  "replay.hub.hedgeBind": "HEDGE पूर्ण ऐतिहासिक इनपुट पसंद करता है; गायब mark/rule/fee/funding प्रति-मद डाउनग्रेड प्रकटीकरण के साथ संस्करणित हाइब्रिड इनपुट बना सकता है। सतत ऐतिहासिक L2 केवल तभी सख्त गेट है जब बुक-असिस्टेड मोड स्पष्ट चुना गया हो।",
